use vstd::prelude::*;

verus! {

    /// Swap the elements at indices `i` and `j` in `arr`.
    ///
    /// Requires:
    ///   * `i < arr.len()` and `j < arr.len()`.
    ///
    /// Ensures:
    ///   * If `i == j`, the vector is unchanged.
    ///   * If `i != j`, then the post‐state `arr@` equals the pre‐state
    ///     `old(arr@)` with elements at `i` and `j` swapped,
    ///     i.e. `old(arr@).update(i, old(arr@)[j]).update(j, old(arr@)[i])`.
    fn swap(arr: &mut Vec<i32>, i: usize, j: usize)
        requires
            i < arr.len(),
            j < arr.len(),
        ensures
            // case i == j: no change
            i == j ==> arr@ == old(arr@),
            // case i != j: exactly those two positions are swapped
            i != j ==> arr@ == old(arr@)
                             .update(i, old(arr@)[j])
                             .update(j, old(arr@)[i]),
    {
        if i != j {
            let tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }
    }
}

